#!/usr/bin/env bash
# Execution VERIFY: PASS when the role sstp_task_role holds the per-type permissions
# 'edit sstp_task_type site setting' and 'view published sstp_task_type site setting entities'
# generated by site_settings_type_permissions, and does NOT hold the global
# 'edit site setting entities' permission (which would defeat the point of per-type access).
# Prints PASS/FAIL; exit 0 pass / 1 fail.
set -uo pipefail
cd /var/www/html
out=$(drush php:eval '
  use Drupal\user\Entity\Role;
  $r = Role::load("sstp_task_role");
  if (!$r) { print "FAIL role sstp_task_role missing\n"; return; }
  $perms = $r->getPermissions();
  $edit = in_array("edit sstp_task_type site setting", $perms, TRUE);
  $view = in_array("view published sstp_task_type site setting entities", $perms, TRUE);
  $global = in_array("edit site setting entities", $perms, TRUE);
  $ok = $edit && $view && !$global;
  print ($ok ? "PASS" : "FAIL") . " edit_type=" . var_export($edit, TRUE)
    . " view_type=" . var_export($view, TRUE)
    . " global_edit=" . var_export($global, TRUE)
    . " perms=[" . implode("|", $perms) . "]\n";
' 2>/dev/null)
echo "$out"
echo "$out" | grep -q '^PASS' && exit 0 || exit 1
